const $=id=>document.getElementById(id),KEY='eris-tracker-v3';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>n==null?'—':Number(n).toLocaleString('en-US',{maximumFractionDigits:6});const money=n=>n==null?'—':'$'+Number(n).toLocaleString('en-US',{maximumFractionDigits:2});
function migrate(old){return {challenges:(old?.challenges||[]).map(c=>{const pub=(c.public||[]).find(r=>r.mine||/^You$/i.test(r.name)),priv=(c.private||[]).find(r=>r.mine||/^You$/i.test(r.name));return {...c,id:c.id||crypto.randomUUID(),tags:c.tags||[],publicRank:c.publicRank??pub?.rank??null,privateRank:c.privateRank??priv?.rank??null,estEarn:c.estEarn??pub?.payout??null,actualEarn:c.actualEarn??null,submissions:c.submissions||[pub&&{id:crypto.randomUUID(),version:'Public (dữ liệu cũ)',score:pub.score},priv&&{id:crypto.randomUUID(),version:'Private (dữ liệu cũ)',score:priv.score}].filter(Boolean)}})}}
let data;try{data=JSON.parse(localStorage.getItem(KEY));if(!data){let old=JSON.parse(localStorage.getItem('eris-challenges-v2'));if(!old){const legacy=JSON.parse(localStorage.getItem('eris-leaderboard-v1'));if(legacy)old={challenges:[legacy]}}data=migrate(old);localStorage.setItem(KEY,JSON.stringify(data))}}catch{data={challenges:[]}}
const SOLUTION_STATUSES=['Approved','Pending review','Rejected'];for(const c of data.challenges)for(const sub of c.submissions)if(!SOLUTION_STATUSES.includes(sub.status))sub.status='Pending review';
let active=null,editingChallenge=null,editingSubmission=null;
function persist(){try{localStorage.setItem(KEY,JSON.stringify(data));return true}catch{$('toast').textContent='Không thể lưu dữ liệu trên trình duyệt.';$('toast').style.display='block';return false}}
function best(c){const scores=c.submissions.map(s=>s.score).filter(Number.isFinite);return scores.length?(c.direction==='asc'?Math.min(...scores):Math.max(...scores)):null}
const TYPE_COLORS={Tabular:['#e5efff','#2b69c7','#a2c1f5'],Classification:['#f0e7ff','#7945bf','#c8acf0'],Regression:['#eef0f3','#687481','#c3cad1'],NLP:['#e1f5e7','#258547','#9cdbaf'],'Computer Vision':['#def5f0','#148777','#8bd6c7'],'Object Detection':['#f2e4ff','#9143c2','#d5a6f0'],'Time Series':['#ffecd9','#be6417','#efba85'],Forecasting:['#fff2cc','#a97808','#e9cb76'],'Anomaly Detection':['#ffe5e3','#ba393c','#f0aaa6'],Recommendation:['#eef0f3','#687481','#c3cad1'],'Sequence To Sequence':['#ddf5eb','#148661','#87d7b9'],'Prompt Engineering':['#ffe4f0','#b6417c','#eda7ca'],RAG:['#def4fc','#1686a6','#89d3e8'],'Fine-Tuning':['#fff2cc','#a97808','#e9cb76'],'From Scratch':['#ffe5e3','#ba393c','#f0aaa6'],'LLM Evaluation':['#f0e7ff','#7945bf','#c8acf0'],Other:['#eef0f3','#687481','#c3cad1']};
function typeStyle(type){const [bg,fg,border]=TYPE_COLORS[type]||TYPE_COLORS.Other;return `--type-bg:${bg};--type-fg:${fg};--type-border:${border}`}
function typeBadge(type){return `<span class="type-badge" style="${typeStyle(type)}">${esc(type)}</span>`}
function colorTypeSelect(){const select=field($('challengeForm'),'type');const [bg,fg,border]=TYPE_COLORS[select.value]||TYPE_COLORS.Other;select.style.backgroundColor=bg;select.style.color=fg;select.style.borderColor=border;for(const option of select.options){const [obg,ofg]=TYPE_COLORS[option.value]||TYPE_COLORS.Other;option.style.backgroundColor=obg;option.style.color=ofg}}
const STATUS_COLORS={'Top leaderboard':['#fff0bb','#906000','#efd07a'],Approved:['#fff0bb','#906000','#efd07a'],Pass:['#dcf5e3','#227141','#a3dfb5'],'Pending review':['#dfedff','#235eb5','#a9cbfa'],Rejected:['#ffe2df','#b32e32','#f5aaa6'],Fail:['#ffe2df','#b32e32','#f5aaa6']};
function colorStatusSelect(select){const apply=(element,value)=>{const [bg,fg,border]=STATUS_COLORS[value]||['#f1f3f1','#68766b','#dce5dd'];element.style.backgroundColor=bg;element.style.color=fg;element.style.borderColor=border};apply(select,select.value);for(const option of select.options)apply(option,option.value)}
function challengeStatus(c){if(c.statusOverride==='Top leaderboard'||Number.isInteger(c.privateRank)&&c.privateRank>=1&&c.privateRank<=3)return 'Top leaderboard';if(!c.submissions.length)return null;return c.submissions.every(s=>s.status==='Rejected')?'Fail':'Pass'}
function statusBadge(status){const kind={'Top leaderboard':'top',Pass:'pass',Fail:'fail',Approved:'approved','Pending review':'pending',Rejected:'rejected'}[status]||'unset';return `<span class="status-badge status-${kind}" ${status?'':'title="Chưa có đủ điểm và baseline"'}>${esc(status||'—')}</span>`}
function renderList(){const q=$('search').value.trim().toLowerCase();$('totalChallenges').textContent=data.challenges.length+' challenges';$('challengeRows').innerHTML=data.challenges.map((c,i)=>({c,i})).filter(({c})=>(c.name+' '+c.tags.join(' ')).toLowerCase().includes(q)).map(({c,i})=>`<tr><td class="rank">${i+1}</td><td><button class="link" data-open="${c.id}">${esc(c.name)}</button></td><td>${typeBadge(c.type)}</td><td><div class="tags">${c.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')||'—'}</div></td><td class="score">${fmt(c.baseline)}</td><td class="score" style="color:#3c7751">${fmt(best(c))}</td><td>${money(c.estEarn)}</td><td>${money(c.actualEarn)}</td><td>${statusBadge(challengeStatus(c))}</td></tr>`).join('')||'<tr><td colspan="9" class="empty">Chưa có challenge phù hợp. Thêm challenge để bắt đầu.</td></tr>'}
function renderDetail(){if(!active)return;$('detailName').textContent=active.name;$('crumbTitle').textContent=active.name;$('detailMeta').innerHTML=typeBadge(active.type)+' '+[...active.tags,active.metric,'Baseline: '+fmt(active.baseline)].map(esc).join(' · ');$('publicRank').textContent=active.publicRank==null?'—':'#'+active.publicRank;$('privateRank').textContent=active.privateRank==null?'—':'#'+active.privateRank;const d=active.publicRank!=null&&active.privateRank!=null?active.publicRank-active.privateRank:null;$('rankChange').textContent=d==null?'Chưa có đủ thứ hạng để so sánh':d===0?'− Không đổi so với Public':(d>0?'↑ Tăng ':'↓ Giảm ')+Math.abs(d)+' hạng so với Public';$('rankChange').style.color=d>0?'#32845a':d<0?'#ba6554':'#829089';$('bestScore').textContent=fmt(best(active));$('scoreNote').textContent=active.direction==='asc'?'Điểm thấp nhất trong các submission':'Điểm cao nhất trong các submission';$('submissionCount').textContent=active.submissions.length+' submissions';$('submissionRows').innerHTML=active.submissions.map((s,i)=>`<tr><td class="rank">${i+1}</td><td><button class="version" data-submission="${s.id}">${esc(s.version)}</button></td><td class="score">${fmt(s.score)}</td><td>${statusBadge(s.status)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">Chưa có submission. Thêm bài giải đầu tiên của bạn.</td></tr>'}
function showList(){active=null;$('listView').hidden=false;$('detailView').hidden=true;$('crumbTitle').textContent='Challenges';renderList()}
function openChallenge(id){active=data.challenges.find(c=>c.id===id);if(!active)return;$('listView').hidden=true;$('detailView').hidden=false;renderDetail()}
const field=(form,name)=>form.querySelector('[name="'+name+'"]');
function challengeDialog(c){editingChallenge=c?.id||null;const f=$('challengeForm');f.reset();const defaults={name:'',type:'Classification',tags:[],metric:'AUC',direction:'desc',baseline:null,estEarn:null,actualEarn:null,publicRank:null,privateRank:null,statusOverride:'',...c};defaults.statusOverride=defaults.statusOverride==='Top leaderboard'?'Top leaderboard':'';defaults.tags=Array.isArray(defaults.tags)?defaults.tags:String(defaults.tags||'').split(',').map(t=>t.trim()).filter(Boolean);for(const key of ['name','type','tags','metric','direction','baseline','estEarn','actualEarn','publicRank','privateRank','statusOverride']){if(key==='type'&&![...field(f,'type').options].some(o=>o.value===defaults.type)){const option=document.createElement('option');option.value=option.textContent=defaults.type;field(f,'type').add(option)}field(f,key).value=key==='tags'?defaults.tags.join(', '):defaults[key]??'';}colorTypeSelect();colorStatusSelect(field(f,'statusOverride'));$('challengeTitle').textContent=c?'Chỉnh sửa challenge':'Thêm challenge';$('deleteChallenge').hidden=!c;$('challengeError').textContent='';$('challengeModal').showModal()}
$('challengeForm').onsubmit=e=>{e.preventDefault();const f=e.currentTarget;if(!f.reportValidity())return;const name=field(f,'name').value.trim();if(!name||data.challenges.some(c=>c.id!==editingChallenge&&c.name.toLowerCase()===name.toLowerCase())){$('challengeError').textContent='Nhập tên challenge duy nhất, không để trống.';return}const values={name,type:field(f,'type').value,tags:[...new Set(field(f,'tags').value.split(',').map(t=>t.trim()).filter(Boolean))],metric:field(f,'metric').value,direction:field(f,'direction').value,statusOverride:field(f,'statusOverride').value};if(!['','Top leaderboard'].includes(values.statusOverride)){$('challengeError').textContent='Chọn trạng thái hợp lệ.';return}for(const k of ['baseline','estEarn','actualEarn','publicRank','privateRank']){const v=field(f,k).value;values[k]=v===''?null:Number(v);if(v!==''&&(!Number.isFinite(values[k])||['publicRank','privateRank'].includes(k)&&(!Number.isInteger(values[k])||values[k]<1)||['estEarn','actualEarn'].includes(k)&&values[k]<0)){$('challengeError').textContent='Kiểm tra lại số tiền và thứ hạng.';return}}if(editingChallenge){const c=data.challenges.find(c=>c.id===editingChallenge);if(!c){$('challengeError').textContent='Challenge không còn tồn tại.';return}Object.assign(c,values);if(active?.id===c.id)active=c}else data.challenges.push({id:crypto.randomUUID(),...values,submissions:[]});if(!persist()){$('challengeError').textContent='Không thể lưu. Hãy kiểm tra bộ nhớ trình duyệt và thử lại.';return}$('challengeModal').close();renderList();renderDetail()};
field($('challengeForm'),'type').onchange=colorTypeSelect;
field($('challengeForm'),'statusOverride').onchange=e=>colorStatusSelect(e.target);
field($('submissionForm'),'status').onchange=e=>colorStatusSelect(e.target);
field($('challengeForm'),'metric').onchange=e=>{field($('challengeForm'),'direction').value=['RMSE','MAE'].includes(e.target.value)?'asc':'desc'};
function submissionDialog(s){editingSubmission=s?.id||null;const f=$('submissionForm');f.reset();field(f,'version').value=s?.version||'';field(f,'score').value=s?.score??'';field(f,'status').value=s?.status||'Pending review';colorStatusSelect(field(f,'status'));$('submissionTitle').textContent=s?'Chỉnh sửa submission':'Thêm submission';$('deleteSubmission').hidden=!s;$('submissionError').textContent='';$('submissionModal').showModal()}
$('submissionForm').onsubmit=e=>{e.preventDefault();const f=e.currentTarget;if(!f.reportValidity())return;const version=field(f,'version').value.trim(),score=Number(field(f,'score').value),status=field(f,'status').value;if(!version||!Number.isFinite(score)||!SOLUTION_STATUSES.includes(status)||active.submissions.some(s=>s.id!==editingSubmission&&s.version.toLowerCase()===version.toLowerCase())){$('submissionError').textContent='Nhập version duy nhất và điểm hợp lệ.';return}if(editingSubmission)Object.assign(active.submissions.find(s=>s.id===editingSubmission),{version,score,status});else active.submissions.push({id:crypto.randomUUID(),version,score,status});persist();$('submissionModal').close();renderDetail();renderList()};
$('challengeRows').onclick=e=>{const b=e.target.closest('[data-open]');if(b)openChallenge(b.dataset.open)};$('submissionRows').onclick=e=>{const b=e.target.closest('[data-submission]');if(b)submissionDialog(active.submissions.find(s=>s.id===b.dataset.submission))};$('search').oninput=renderList;$('back').onclick=showList;$('navChallenges').onclick=showList;$('addChallenge').onclick=()=>challengeDialog();$('editChallenge').onclick=()=>challengeDialog(active);$('addSubmission').onclick=()=>submissionDialog();$('cancelChallenge').onclick=()=>$('challengeModal').close();$('cancelSubmission').onclick=()=>$('submissionModal').close();$('deleteSubmission').onclick=()=>{if(confirm('Xóa submission này?')){active.submissions=active.submissions.filter(s=>s.id!==editingSubmission);persist();$('submissionModal').close();renderDetail();renderList()}};$('deleteChallenge').onclick=()=>{if(confirm('Xóa challenge và các submission thuộc challenge này?')){data.challenges=data.challenges.filter(c=>c.id!==editingChallenge);if(!persist()){$('challengeError').textContent='Không thể lưu. Hãy kiểm tra bộ nhớ trình duyệt và thử lại.';return}$('challengeModal').close();showList()}};showList();
